INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass jede Tabelle einen Primärschlüssel benötigt?', 2, '[{"text": "Nein", "correct": true, "because": "Empfohlen, aber technisch optional"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element verbindet zwei Tabellen miteinander?', 3, '[{"text": "Fremdschlüssel", "correct": true, "because": "Verweist auf Primärschlüssel"}, {"text": "Index", "correct": false, "because": "Optimiert Abfragen"}, {"text": "Trigger", "correct": false, "because": "Für Aktionen, nicht Verknüpfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien machen ein Tabellenmodell effizient?', 5, '[{"text": "Normalisierung", "correct": true, "because": "Vermeidet Redundanzen"}, {"text": "Referenzielle Integrität", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Hohe Zeilenanzahl", "correct": false, "because": "Kein Effizienzfaktor"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Nur kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Tabellen sind durch Schlüssel verknüpft. b) Jede Tabelle braucht mehrere Schlüssel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ein Schlüssel reicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Gestaltung eines Tabellenmodells?', 4, '[{"text": "Beziehungen", "correct": false, "because": "Kern des Modells"}, {"text": "Normalisierung", "correct": false, "because": "Sichert Effizienz"}, {"text": "Farbschema", "correct": true, "because": "Kein funktionaler Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Primärschlüssel eindeutig sein muss?', 2, '[{"text": "Ja", "correct": true, "because": "Garantiert Einzigartigkeit"}, {"text": "Nein", "correct": false, "because": "Eindeutigkeit ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Konzept verhindert verwaiste Datensätze?', 4, '[{"text": "Referenzielle Integrität", "correct": true, "because": "Sichert gültige Verweise"}, {"text": "Denormalisierung", "correct": false, "because": "Erhöht Redundanzen"}, {"text": "Caching", "correct": false, "because": "Für Leistung, nicht Konsistenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Normalisierung immer Speicher spart. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kann mehr Tabellen erzeugen"}, {"text": "Ja", "correct": false, "because": "Fokus auf Redundanz, nicht Speicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Fremdschlüssel immer ein Primärschlüssel?', 2, '[{"text": "Nein", "correct": true, "because": "Verweist, identifiziert nicht"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Rollen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördern die Konsistenz eines Datenmodells?', 5, '[{"text": "Fremdschlüssel", "correct": true, "because": "Sichern Beziehungen"}, {"text": "Constraints", "correct": true, "because": "Erzwingen Regeln"}, {"text": "Hohe Tabellenanzahl", "correct": false, "because": "Kein Konsistenzfaktor"}, {"text": "Manuelle Eingaben", "correct": false, "because": "Fehleranfällig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Modellierung einer Datenbank?', 4, '[{"text": "Klare Beziehungen", "correct": true, "because": "Sichert Struktur"}, {"text": "Maximale Datenmenge", "correct": false, "because": "Sekundär"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Normalisierung reduziert Anomalien. b) Sie macht Abfragen immer schneller.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann Leistung beeinträchtigen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Tabellenmodell?', 3, '[{"text": "Primärschlüssel", "correct": false, "because": "Fördert Eindeutigkeit"}, {"text": "Fremdschlüssel", "correct": false, "because": "Sichert Beziehungen"}, {"text": "Tabellenfarben", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich Beziehungen zwischen Tabellen definiere?', 4, '[{"text": "Fremdschlüssel auf Primärschlüssel", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Nur Tabellennamen", "correct": false, "because": "Keine Beziehung"}, {"text": "Zufällige Spalten", "correct": false, "because": "Fehlt Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Modell ohne Schlüssel funktioniert. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Technisch möglich, aber riskant"}, {"text": "Nein", "correct": false, "because": "Schlüssel fördern Konsistenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, Datenanomalien zu vermeiden?', 3, '[{"text": "Normalisierung", "correct": true, "because": "Strukturiert Daten klar"}, {"text": "Denormalisierung", "correct": false, "because": "Erhöht Anomalien"}, {"text": "Hohe Redundanz", "correct": false, "because": "Verursacht Probleme"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Primärschlüssel mehrere Spalten umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "Zusammengesetzte Schlüssel möglich"}, {"text": "Nein", "correct": false, "because": "Mehrspaltige Schlüssel erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein gut gestaltetes Tabellenmodell?', 5, '[{"text": "Konsistenz", "correct": true, "because": "Schlüssel sichern Beziehungen"}, {"text": "Skalierbarkeit", "correct": true, "because": "Struktur erleichtert Erweiterung"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Diagramme", "correct": false, "because": "Nur visuelle Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Datenmodellierung unwichtig?', 3, '[{"text": "Schlüsseldefinition", "correct": false, "because": "Sichert Struktur"}, {"text": "Beziehungsregeln", "correct": false, "because": "Fördern Konsistenz"}, {"text": "Spaltennamenstil", "correct": true, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich eine konsistente Datenbank entwerfe?', 4, '[{"text": "Normalisieren und Schlüssel setzen", "correct": true, "because": "Sichert Struktur"}, {"text": "Zufällige Tabellen", "correct": false, "because": "Fehlt Konsistenz"}, {"text": "Ohne Beziehungen", "correct": false, "because": "Verursacht Chaos"}]');
